src=[dict(id='nccp',title='NCCP 00702 v2 · Entrectinib monotherapy – adult',url=N),dict(id='smpc',title='EMA Rozlytrek product information · updated 27 March 2025',url=S),dict(id='ros1-trial',title='Fan et al. 2024 · ROS1 integrated analysis',url=P),dict(id='ntrk-trial',title='Demetri et al. 2022 · adult NTRK integrated analysis',url=T),dict(id='ntrk-lung-trial',title='Cho et al. 2024 · NTRK-positive NSCLC analysis',url=L),dict(id='antiemetic',title='NCCP NCIS antiemetics V8 · parenteral scope',url=A),dict(id='oral-antiemetic',title='NCCP SACT antiemetic guidance V6 · oral therapy',url=O),dict(id='map',title='HSE managed access protocols · ROS1 and NTRK',url=MAP)]
scope='This adult suite covers entrectinib alone for ROS1-positive advanced NSCLC before any ROS1 inhibitor (00702a), or a separate NTRK gene-fusion solid-tumour indication with no previous NTRK inhibitor and no satisfactory treatment options (00702b). Molecular tests and Irish access criteria must be confirmed. The adult 600 mg schedule does not apply to children.'
schedule='The usual adult starting dose is 600 mg by mouth once daily, every day without a planned rest week. Use your prescribed dose. Treatment continues while helping and side effects remain acceptable; there is no fixed number of cycles.'
administration='Take whole capsules with or without food; do not crush or chew. Avoid grapefruit, grapefruit products and Seville oranges. If a dose is missed, take it unless the next dose is due within 12 hours; confirm the exact boundary with your pharmacist. The leaflet permits repeating whole capsules after immediate vomiting: follow your written plan and call if uncertain. Suspension or tube administration requires separate pharmacy instructions.'
baseline='Before starting: confirm fusion, previous targeted treatment, access and pregnancy precautions; blood count, kidney/liver tests, uric acid, ECG/electrolytes and cognitive symptoms. Heart-pumping assessment is needed for heart-failure symptoms or risk; brain imaging follows the Consultant plan.'
ongoing='During treatment: repeat blood count, kidney/liver tests and uric acid at agreed reviews. Repeat ECG/electrolytes after one month, then periodically as indicated. Assess thinking/memory, heart symptoms, vision and bone pain; scans follow the Consultant plan.'
monitoring='Blood count, kidney/liver tests, uric acid and ECG/electrolytes before starting. Repeat ECG/electrolytes after one month, then periodically as indicated; regular blood tests and symptom reviews. Heart-pumping tests depend on symptoms/risk. Scans follow your Consultant’s plan. Confirm who arranges and reviews each check.'
reproduction='Avoid pregnancy. Women who could become pregnant need highly effective contraception during treatment and for at least five weeks afterwards; add a barrier method if using systemic hormonal contraception. Men with partners who could become pregnant need highly effective contraception during treatment and for at least three months afterwards. Do not breastfeed during treatment. Discuss fertility and family plans before starting.'
interactions='Give the team a complete medicine and supplement list, including St John’s wort. CYP3A inhibitors/inducers and medicines affecting heart rhythm need pharmacy review. Do not change the cancer dose yourself; temporary interaction doses differ from toxicity reductions.'
urgent='Call the oncology team urgently for new or worsening breathlessness, swelling, palpitations or fainting; marked confusion or memory change; fever, jaundice, severe diarrhoea or inability to drink. Report new visual disturbance and focal bone pain promptly. Follow your unit’s temperature/contact instructions. Severe breathing difficulty, chest pain or collapse needs emergency help.'
risks=['Dizziness, altered thinking or memory','Heart failure and heart-rhythm changes','Taste change, nausea, constipation or diarrhoea','Swelling, weight gain and tiredness','Liver injury and low blood counts','Raised uric acid and kidney-test changes','Visual disturbance, nerve symptoms and fractures','Potential harm in pregnancy']
agent=dict(id='entrectinib',name='Entrectinib',alias='Rozlytrek',type='ROS1 / TRK targeted therapy',mechanism='Blocks abnormal ROS1 or TRK growth signals',explanation='Entrectinib inhibits proteins made by selected ROS1 or NTRK gene fusions. Blocking these signals can slow cancer growth. The relevant fusion, tumour setting and previous medicines determine eligibility; ROS1 and NTRK are different indications.',visual=['Matching gene fusion identified','Abnormal growth signalling blocked','Cancer growth may slow'],watch='Report heart, thinking/memory, vision and bone symptoms early.',source_ids=['nccp','smpc'],risks=risks,symptoms=['Dizziness or fainting','Thinking / memory changes','Breathlessness or swelling','Nausea / bowel changes','Visual disturbance','Bone / muscle / nerve symptoms'])
rows=[dict(label='Treatment',cells=['Confirm ROS1 or NTRK setting and prescription','Daily capsules without a rest week','Continue prescribed dose if authorised','Review benefit and tolerability','Team authorises hold, restart, switch or stop']),dict(label='Blood tests',cells=['Blood count, kidney/liver tests and uric acid','Repeat at agreed reviews','Continue regular testing','Extra tests for symptoms/abnormal results','Follow recovery and unresolved effects']),dict(label='Heart checks',cells=['ECG/electrolytes; LVEF if symptoms/risk','ECG/electrolytes after one month','Further checks periodically as indicated','Assess new breathlessness/swelling/fainting','Confirm recovery before restarting']),dict(label='Symptoms and supply',cells=['Cognition, vision, neuropathy and medicine list','Review symptoms, adherence and supply','Report thinking/memory, visual or bone changes','Review interactions and practical support','Continue contact and reproductive precautions']),dict(label='Cancer assessment',cells=['Validated fusion, stage and prior therapy','Clinical review','Scans at Consultant-directed intervals','Discuss response/progression and preferences','Agree next treatment or follow-up'])]
stages=['Before treatment','First month','Ongoing daily treatment','Benefit / toxicity review','Hold or change']
evidence_intro='Separate studies found tumour shrinkage and periods of cancer control in ROS1-positive lung cancer and NTRK fusion-positive tumours, including some brain metastases. These studies generally had no randomised comparison group; they do not establish an individual survival benefit or superiority over other targeted medicines.'
limitations=['ROS1 and NTRK are separate molecular populations. Results are not transferable between them or to patients previously treated with the excluded targeted inhibitor.','The cited integrated studies were single-arm phase I/II cohorts; they cannot show head-to-head superiority or a causal survival gain.','The NTRK all-tumour result combines small and diverse tumour groups. The 2024 NTRK lung subset is separately labelled and should not be assigned to other tissues.','NCCP eligibility prints age >18 and lists CNS involvement for ROS1, while the broad adult indication/EMA licence do not require brain disease; clarify current MAP interpretation rather than inventing eligibility.','NCCP v2 capsule-opening restriction predates current SmPC suspension instructions; pharmacy must direct any alternative administration. Independent clinical, pharmacy and PPI review remains pending.']
